import{r as e}from"./rolldown-runtime-hePW80VL.js";import{b as t,v as n}from"./r3f-x1z21uF6.js";import{P as r,o as i}from"./index-C0m700pS.js";var a=e(t(),1),o=[{cat:`dl`,term:`Receptive field`,def:`The region of the input that can influence one unit of a feature map. It grows with depth, kernel size, stride and dilation.`,see:`cnn`},{cat:`dl`,term:`Weight sharing`,def:`Reusing the same kernel at every spatial position, which gives translation equivariance and a small parameter count.`,see:`cnn`},{cat:`dl`,term:`Residual connection`,def:`A skip path y = x + F(x) that lets gradients flow unimpeded through very deep networks (ResNet, Transformer).`,see:`cnn`},{cat:`dl`,term:`Momentum`,def:`An exponential moving average of past gradients that damps oscillation across ravines and speeds travel along them.`,see:`optim`},{cat:`dl`,term:`Adam`,def:`Optimizer combining momentum with per-parameter adaptive step sizes from a running average of squared gradients, with bias correction.`,see:`optim`},{cat:`dl`,term:`Learning-rate schedule`,def:`A rule for changing the learning rate during training: warmup, cosine decay, step decay, linear decay.`,see:`optim`},{cat:`dl`,term:`Backprop through time (BPTT)`,def:`Backpropagation applied to an RNN unrolled across time steps; gradients are products of Jacobians over the sequence.`,see:`rnn`},{cat:`dl`,term:`Vanishing / exploding gradient`,def:`Repeated multiplication by Jacobians with norm below / above 1 makes gradients shrink or blow up exponentially with depth or sequence length.`,see:`rnn`},{cat:`dl`,term:`Gradient clipping`,def:`Rescaling the gradient when its norm exceeds a threshold to tame exploding gradients.`,see:`rnn`},{cat:`dl`,term:`Cell state`,def:`The LSTM's long-term memory vector, updated additively under gate control so gradients can persist across many steps.`,see:`lstm`},{cat:`dl`,term:`Gate`,def:`A sigmoid-valued vector in (0,1) multiplied element-wise to decide how much information to let through.`,see:`lstm`},{cat:`dl`,term:`Update gate`,def:`GRU gate z that interpolates between the previous hidden state and the new candidate.`,see:`gru`},{cat:`dl`,term:`Attention`,def:`A differentiable lookup: a query is compared with keys to give weights that average the values.`,see:`attention`},{cat:`dl`,term:`Teacher forcing`,def:`Training a decoder by feeding it ground-truth previous tokens instead of its own predictions.`,see:`attention`},{cat:`dl`,term:`Self-attention`,def:`Attention where queries, keys and values all come from the same sequence, letting every token read every other token.`,see:`transformer`},{cat:`dl`,term:`Multi-head attention`,def:`Running h attention operations in parallel in lower-dimensional subspaces and concatenating the results.`,see:`transformer`},{cat:`dl`,term:`Positional encoding`,def:`Information injected into token embeddings so an order-agnostic attention layer can use position (sinusoidal, learned, rotary).`,see:`transformer`},{cat:`dl`,term:`Layer normalization`,def:`Normalizes each token's features to zero mean / unit variance and rescales with learned gain and bias. Pre-LN is standard.`,see:`transformer`},{cat:`dl`,term:`Masked language modeling`,def:`BERT's pre-training objective: hide ~15% of tokens and predict them from bidirectional context.`,see:`bert`},{cat:`dl`,term:`Fine-tuning`,def:`Continuing training of a pre-trained model on a smaller task-specific dataset.`,see:`bert`},{cat:`dl`,term:`Causal mask`,def:`A lower-triangular attention mask preventing a token from attending to future positions.`,see:`gpt`},{cat:`dl`,term:`Temperature`,def:`Divides logits before softmax: T<1 sharpens the distribution, T>1 flattens it.`,see:`gpt`},{cat:`dl`,term:`Top-p (nucleus) sampling`,def:`Sample only from the smallest set of tokens whose cumulative probability exceeds p.`,see:`gpt`},{cat:`dl`,term:`KV cache`,def:`Stored keys and values of past tokens so each new token costs O(n) attention rather than recomputing the whole prefix.`,see:`gpt`},{cat:`dl`,term:`RoPE`,def:`Rotary position embedding: rotates query/key pairs by position-dependent angles so dot products depend only on relative offset.`,see:`modern`},{cat:`dl`,term:`Grouped-query attention (GQA)`,def:`Several query heads share one key/value head, shrinking the KV cache.`,see:`modern`},{cat:`dl`,term:`Mixture of Experts (MoE)`,def:`A layer with many expert FFNs where a router activates only the top-k per token, decoupling parameters from compute.`,see:`modern`},{cat:`dl`,term:`LoRA`,def:`Low-rank adaptation: freeze W and learn a rank-r update BA, training far fewer parameters.`,see:`modern`},{cat:`dl`,term:`Scaling law`,def:`Empirical power-law relationship between loss and parameters, data and compute.`,see:`modern`},{cat:`cuda`,term:`Thread`,def:`The smallest unit of execution in CUDA; each runs the same kernel with its own indices and registers.`,see:`cuda-exec`},{cat:`cuda`,term:`Block`,def:`A group of up to 1024 threads that run on one SM, can synchronize with __syncthreads() and share shared memory.`,see:`cuda-exec`},{cat:`cuda`,term:`Grid`,def:`All blocks launched by one kernel invocation. Blocks are independent and can run in any order.`,see:`cuda-exec`},{cat:`cuda`,term:`Warp`,def:`A group of 32 consecutive threads that execute in lockstep (SIMT). The real unit of scheduling.`,see:`cuda-exec`},{cat:`cuda`,term:`Streaming multiprocessor (SM)`,def:`The GPU's compute tile: warp schedulers, CUDA cores, tensor cores, register file and shared memory.`,see:`cuda-exec`},{cat:`cuda`,term:`Global memory`,def:`Off-chip DRAM (HBM/GDDR) visible to all threads; large, high-bandwidth and high-latency.`,see:`cuda-memory`},{cat:`cuda`,term:`Shared memory`,def:`Fast on-chip, software-managed scratchpad shared by the threads of a block, organized in 32 banks.`,see:`cuda-tiled`},{cat:`cuda`,term:`Roofline model`,def:`Performance is bounded by min(peak FLOPS, bandwidth × arithmetic intensity); tells you if a kernel is compute- or memory-bound.`,see:`cuda-memory`},{cat:`cuda`,term:`Arithmetic intensity`,def:`FLOPs performed per byte moved to/from memory.`,see:`cuda-memory`},{cat:`cuda`,term:`Tiling`,def:`Partitioning data into blocks that fit in fast memory so each global load is reused many times.`,see:`cuda-tiled`},{cat:`cuda`,term:`Cooperative load`,def:`Threads of a block together copy a tile from global memory into shared memory, one (or a few) elements each, then synchronise.`,see:`cuda-tiled`},{cat:`cuda`,term:`__syncthreads`,def:`Block-wide barrier and memory fence: every thread of the block must reach it, after which prior shared and global writes are visible to the whole block.`,see:`cuda-tiled`},{cat:`cuda`,term:`Halo (ghost cells)`,def:`Extra elements loaded around a tile so a stencil or convolution can read neighbours without going back to global memory.`,see:`cuda-tiled`},{cat:`cuda`,term:`GEMM`,def:`General matrix multiply C = AB (or αAB+βC). The canonical kernel for teaching tiling; production code calls cuBLAS / CUTLASS.`,see:`cuda-tiled`},{cat:`cuda`,term:`Dynamic shared memory`,def:`Per-launch shared-memory size passed as the third kernel-launch parameter, declared extern __shared__.`,see:`cuda-tiled`},{cat:`cuda`,term:`Memory coalescing`,def:`When a warp's accesses fall in few contiguous segments, the hardware merges them into few transactions.`,see:`cuda-coalesce`},{cat:`cuda`,term:`Bank conflict`,def:`Two threads of a warp access different addresses in the same shared-memory bank, serializing the access.`,see:`cuda-coalesce`},{cat:`cuda`,term:`Broadcast`,def:`Several lanes of a warp reading the same shared-memory address. Served in one access; it is not a bank conflict.`,see:`cuda-coalesce`},{cat:`cuda`,term:`Shared-memory padding`,def:`An odd leading dimension (tile[32][33]) so a column access hits every bank instead of one.`,see:`cuda-coalesce`},{cat:`cuda`,term:`Stride`,def:`The gap, in elements, between addresses touched by consecutive lanes. Stride 1 coalesces; large strides do not.`,see:`cuda-coalesce`},{cat:`cuda`,term:`Warp divergence`,def:`Threads of one warp taking different branches; the paths are executed serially with inactive lanes masked.`,see:`cuda-warp`},{cat:`cuda`,term:`__shfl_down_sync`,def:`Warp primitive that reads a register from the lane Δ above the caller. The reduction with offsets 16, 8, 4, 2, 1 leaves the sum in lane 0.`,see:`cuda-warp`},{cat:`cuda`,term:`SIMT`,def:`Single instruction, multiple threads: one warp of 32 lanes is issued together, each lane with its own registers and predicate.`,see:`cuda-warp`},{cat:`cuda`,term:`Reconvergence`,def:`The point where a divergent warp joins back onto one path. On Volta and later you must not assume it happened unless you call a _sync primitive.`,see:`cuda-warp`},{cat:`cuda`,term:`__shfl_xor_sync`,def:`Butterfly shuffle: lane ℓ reads lane ℓ XOR Δ. A five-step reduction leaves the warp sum in every lane.`,see:`cuda-warp`},{cat:`cuda`,term:`Warp reduction`,def:`Summing (or maxing) 32 registers with shuffles. A block reduction is one warp reduction per warp, one barrier, then a second warp reduction of the partials.`,see:`cuda-warp`},{cat:`cuda`,term:`__ballot_sync`,def:`Packs one predicate per lane into a 32-bit word. popc of the bits below you is a warp-local compaction index.`,see:`cuda-warp`},{cat:`cuda`,term:`Occupancy`,def:`Resident warps per SM divided by the SM maximum (64 on A100/H100, 48 on Ada). Capped by registers, shared memory, warp slots and block slots.`,see:`cuda-occupancy`},{cat:`cuda`,term:`Register spilling`,def:`When a kernel needs more registers than the budget allows, values spill to local memory, which travels through L1/L2 like a global access.`,see:`cuda-occupancy`},{cat:`cuda`,term:`__launch_bounds__`,def:`A kernel hint, __launch_bounds__(maxThreads, minBlocks), that forces the compiler to stay within a register budget so at least minBlocks can reside on one SM.`,see:`cuda-occupancy`},{cat:`cuda`,term:`Latency hiding`,def:`Keeping enough eligible warps, or enough independent instructions per warp, that a stall on one warp does not leave the SM's schedulers idle.`,see:`cuda-occupancy`},{cat:`cuda`,term:`Stream`,def:`An ordered queue of GPU work. Operations in one stream run in order; operations in different streams may overlap on the copy engines and the SMs.`,see:`cuda-streams`},{cat:`cuda`,term:`Pinned memory`,def:`Page-locked host memory from cudaMallocHost. The GPU can DMA it directly, so cudaMemcpyAsync returns immediately and overlaps compute.`,see:`cuda-streams`},{cat:`cuda`,term:`Copy engine`,def:`DMA hardware that moves bytes between host and device. Data-centre GPUs have two, so H2D and D2H can run together and both can overlap a kernel.`,see:`cuda-streams`},{cat:`cuda`,term:`cudaStreamWaitEvent`,def:`Makes one stream wait until an event recorded in another stream is signaled. The host thread is not part of the wait.`,see:`cuda-streams`},{cat:`cuda`,term:`Legacy default stream`,def:`The NULL stream. It waits for every blocking stream and then blocks them, so a kernel launched with no stream argument serializes with those streams.`,see:`cuda-streams`},{cat:`cuda`,term:`Tensor Core`,def:`Hardware that computes a small matrix multiply-accumulate per instruction (a 16×16×16 FP16 tile in the WMMA API), accumulated in FP32. Dense peaks are far above the CUDA-core FP32 rate.`,see:`cuda-flash`},{cat:`cuda`,term:`WMMA`,def:`Warp-level matrix instructions: wmma::load_matrix_sync, mma_sync, store_matrix_sync. All 32 lanes of the warp must execute them together.`,see:`cuda-flash`},{cat:`cuda`,term:`FlashAttention`,def:`Exact attention in SRAM tiles. Online softmax updates the output as each K/V tile arrives, so the N×N score matrix is never written to HBM.`,see:`cuda-flash`},{cat:`cuda`,term:`Online softmax`,def:`Softmax that keeps a running max m and sum ℓ. When a later tile raises the max, earlier mass is rescaled by e^(m−m′). The result matches the full-row softmax.`,see:`cuda-flash`},{cat:`cuda`,term:`Score matrix`,def:`The N×N matrix of attention logits QK^T. Writing it dominates HBM traffic; FlashAttention keeps each tile in SRAM and drops it.`,see:`cuda-flash`},{cat:`cuda`,term:`Register file`,def:`The fastest storage on the SM: 64K 32-bit registers per SM, up to 255 per thread. Registers are not addressable, so dynamically indexed arrays go to local memory.`,see:`cuda-memory`},{cat:`cuda`,term:`Local memory`,def:`Thread-private storage for dynamically indexed arrays and spilled registers. Despite the name it lives in device memory (cached by L1/L2).`,see:`cuda-memory`},{cat:`cuda`,term:`Constant memory`,def:`64 KB read-only space served by a dedicated cache that broadcasts one address to a whole warp; ideal for uniformly read coefficients.`,see:`cuda-memory`},{cat:`cuda`,term:`L2 cache`,def:`Chip-wide cache shared by all SMs (40 MB on A100, 50 MB on H100) through which all global traffic and atomics pass.`,see:`cuda-memory`},{cat:`cuda`,term:`HBM`,def:`High-bandwidth memory: stacked DRAM beside the GPU die on a silicon interposer, giving 2-3+ TB/s on data-centre GPUs.`,see:`cuda-memory`},{cat:`cuda`,term:`Cache line / sector`,def:`Global memory is moved in 128-byte lines tracked as 32-byte sectors; a warp's accesses are merged into the minimum number of sectors.`,see:`cuda-memory`},{cat:`cuda`,term:`Effective bandwidth`,def:`Bytes actually read plus written divided by kernel time; compare with the theoretical peak to judge a memory-bound kernel.`,see:`cuda-memory`},{cat:`cuda`,term:`Average memory access time (AMAT)`,def:`Hit-rate-weighted average latency over the memory hierarchy: p1·L1 + p2·L2 + p3·HBM.`,see:`cuda-memory`},{cat:`cuda`,term:`Little's law`,def:`Bytes in flight = bandwidth × latency; the reason GPUs need many resident warps or many independent loads per thread.`,see:`cuda-memory`},{cat:`cuda`,term:`Ridge point`,def:`Arithmetic intensity π/β where the roofline's bandwidth slope meets the compute ceiling; kernels left of it are memory-bound, right of it compute-bound.`,see:`cuda-memory`},{cat:`cuda`,term:`Memory-bound / compute-bound`,def:`A kernel is memory-bound if bytes moved, not arithmetic, limits its runtime (low FLOP/byte), and compute-bound in the opposite case.`,see:`cuda-memory`}],s=n();function c(){let[e,t]=(0,a.useState)(``),[n,c]=(0,a.useState)(`all`),l=(0,a.useMemo)(()=>{let t=e.trim().toLowerCase();return o.filter(e=>(n===`all`||e.cat===n)&&(!t||(e.term+` `+e.def).toLowerCase().includes(t))).sort((e,t)=>e.term.localeCompare(t.term))},[e,n]);return(0,s.jsxs)(i.div,{className:`page`,initial:{opacity:0,y:14},animate:{opacity:1,y:0},exit:{opacity:0},children:[(0,s.jsxs)(`div`,{className:`crumbs`,children:[(0,s.jsx)(r,{to:`/`,children:`Atlas`}),` / Reference`]}),(0,s.jsx)(`h1`,{children:`Glossary`}),(0,s.jsx)(`p`,{className:`lede`,children:`Short, precise definitions of the terms used throughout the atlas. Each links to the chapter that develops it.`}),(0,s.jsxs)(`div`,{className:`controls`,style:{marginBottom:18},children:[(0,s.jsx)(`input`,{className:`gsearch`,placeholder:`Filter terms…`,value:e,onChange:e=>t(e.target.value)}),[[`all`,`All`],[`dl`,`Deep learning`],[`cuda`,`CUDA`]].map(([e,t])=>(0,s.jsx)(`button`,{className:`seg`+(n===e?` on`:``),onClick:()=>c(e),children:t},e))]}),(0,s.jsxs)(`div`,{className:`gloss`,children:[l.map(e=>(0,s.jsxs)(`div`,{className:`gitem`,children:[(0,s.jsxs)(`div`,{className:`gterm`,children:[e.term,` `,(0,s.jsx)(`span`,{className:`gcat `+e.cat,children:e.cat===`dl`?`DL`:`CUDA`})]}),(0,s.jsx)(`p`,{children:e.def}),e.see&&(0,s.jsx)(r,{to:`/t/`+e.see,children:`Read more →`})]},e.term)),!l.length&&(0,s.jsx)(`p`,{children:`No terms match.`})]})]})}export{c as default};